    45|export async function askAI(prompt: string, opts: { systemPrompt?: string; maxTokens?: number; timeoutMs?: number } = {}): Promise<AIReasoningResult> {
    46|  const apiKey = resolveApiKey();
    47|  if (!apiKey) {
    48|    return { ok: false, content: '', error: 'AI gateway key not configured (OPENAI_API_KEY or AI_GATEWAY_API_KEY).', model: 'none', usage: null };
    49|  }
    50|  const model = resolveModel();
    51|  const messages: { role: string; content: string }[] = [];
    52|  if (opts.systemPrompt) messages.push({ role: 'system', content: opts.systemPrompt });
    53|  messages.push({ role: 'user', content: prompt });
    54|
    55|  const controller = new AbortController();
    56|  const timeout = setTimeout(() => controller.abort(), opts.timeoutMs ?? 60_000);
    57|  try {
    58|    const res = await fetch(GATEWAY_URL, {
    59|      method: 'POST',
    60|      headers: {
    61|        Authorization: `Bearer ${apiKey}`,
    62|        'Content-Type': 'application/json',
    63|      },
    64|      body: JSON.stringify({
    65|        model,
    66|        messages,
    67|        max_tokens: opts.maxTokens ?? 2000,
    68|        temperature: 0.2,
    69|      }),
    70|      signal: controller.signal,
    71|    });
