    76|    const data = (await res.json()) as Record<string, unknown>;
    77|    const choices = Array.isArray(data.choices) ? (data.choices as Array<Record<string, unknown>>) : [];
    78|    const message = choices[0]?.message as Record<string, unknown> | undefined;
    79|    const content = typeof message?.content === 'string' ? message.content : '';
    80|    const usage = data.usage as Record<string, unknown> | undefined;
    81|    return {
    82|      ok: true,
    83|      content,
    84|      error: null,
