   120|  let readerRowCount = 0;
   121|  let readerError: string | null = null;
   122|
   123|  // Read messages through the EXACT same proven runtime reader the chat UI and
   124|  // /room-status use (loadRecentMessages). The previous bespoke query in this
   125|  // audit reported 0 even when the conversation had a full durable transcript —
   126|  // reusing the battle-tested reader eliminates that parallel-implementation
   127|  // drift so the audit always reflects what the owner actually sees.
   128|  try {
   129|    const messages = await loadRecentMessages(client, tables, conversationId);
   130|    readerRowCount = messages.length;
   131|    for (const message of messages) {
   132|      const role = readString(message.sender_role).toLowerCase();
   133|      if (role === 'assistant') {
   134|        assistantMessageCount += 1;
   135|      } else if (role !== 'system') {
   136|        userMessageCount += 1;
   137|      }
   138|      if (!hasVisibleBody && readNullableString(message.body)) {
   139|        hasVisibleBody = true;
   140|      }
   141|    }
