   147|  let failedMessageCount = 0;
   148|  const models = new Set<string>();
   149|  let requestStatuses: string[] = [];
   150|  if (tables.aiRequests) {
   151|    try {
   152|      const requestResult = await scoped
   153|        .from(tables.aiRequests)
   154|        .select('status, model')
   155|        .eq('conversation_id', conversationId)
   156|        .order('created_at', { ascending: false })
   157|        .limit(MAX_REQUESTS_PER_CONVERSATION);
   158|
   159|      const rows = ((requestResult.data as Record<string, unknown>[] | null) ?? []);
   160|      requestStatuses = rows.map((row) => readString(row.status).toLowerCase()).filter(Boolean);
   161|      failedMessageCount = requestStatuses.filter((status) => status === 'failed').length;
   162|      for (const row of rows) {
   163|        const model = readNullableString(row.model);
   164|        if (model) models.add(model);
