   189|  return {
   190|    conversationId,
   191|    slug: readNullableString(conversation.slug),
   192|    title: readNullableString(conversation.title),
   193|    createdAt: readNullableString(conversation.created_at),
   194|    lastMessageAt: readNullableString(conversation.last_message_at) ?? readNullableString(conversation.updated_at),
   195|    userMessageCount,
   196|    assistantMessageCount,
   197|    failedMessageCount,
